import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"配置工程 AI 模型","description":"在工程中添加模型服务和凭据，选择并测试模型，理解共享范围及修改生效方式。","frontmatter":{"title":"配置工程 AI 模型","description":"在工程中添加模型服务和凭据，选择并测试模型，理解共享范围及修改生效方式。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/ai-models.md","filePath":"zh/使用指南/配置工程AI模型.md"}'),o={name:"zh/guide/ai-models.md"};function i(l,t,h,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="配置工程-ai-模型" tabindex="-1">配置工程 AI 模型 <a class="header-anchor" href="#配置工程-ai-模型" aria-label="Permalink to &quot;配置工程 AI 模型&quot;">​</a></h1><p>模型、服务商（Provider）、接口密钥（API Key）等名词，见<a href="/induframe-docs/zh/reference/glossary.html">常用术语解释</a>。不理解字段含义时先确认，不随意填写凭据或地址。</p><p>AI 助手需要一个可访问、具备额度且配置正确的模型服务。本页由获准维护当前工程模型配置的成员操作；普通使用者已有可用模型时，直接选择即可。</p><p><strong>同一工程的模型配置与凭据共享。</strong> 修改、删除、退出服务商登录或消耗模型额度都可能影响共同使用者。使用组织批准的凭据，不把个人密钥当成在此严格隔离保存。</p><h2 id="_1-打开配置面板" tabindex="-1">1. 打开配置面板 <a class="header-anchor" href="#_1-打开配置面板" aria-label="Permalink to &quot;1. 打开配置面板&quot;">​</a></h2><p>进入工程“应用开发”的 AI 区域，打开 <strong>“设置” → “模型”</strong>。缺少模型或凭据的错误提示也可直接点击 <strong>“打开工程模型配置”</strong>。</p><p>面板显示“工程模型配置”。先查看是否已有适用的服务商和模型，不要一开始就重复添加。</p><h2 id="_2-先准备必要资料" tabindex="-1">2. 先准备必要资料 <a class="header-anchor" href="#_2-先准备必要资料" aria-label="Permalink to &quot;2. 先准备必要资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资料</th><th>应向谁确认</th></tr></thead><tbody><tr><td>服务商及可使用的账号</td><td>组织或模型服务管理员</td></tr><tr><td>API Key 或该服务要求的登录方式</td><td>服务商及组织的凭据管理负责人</td></tr><tr><td>模型标识</td><td>服务商实际提供的模型 ID，不只是产品宣传名称</td></tr><tr><td>自定义服务的 Base URL、API 类型</td><td>提供该服务的人员，地址和协议必须匹配</td></tr><tr><td>网络与额度</td><td>开发节点能访问服务，账号允许调用该模型且有可用额度</td></tr></tbody></table><p>模型请求从平台开发环境发出，不是直接从你的电脑发出。你的电脑能打开一个服务地址，不代表开发节点也能访问；<code>127.0.0.1</code> 也不代表你的个人电脑。</p><p>不要把服务商官网登录页、普通网页地址或不匹配的 API 协议填写为模型接口。</p><h2 id="_3-使用已有服务商-或添加自定义服务" tabindex="-1">3. 使用已有服务商，或添加自定义服务 <a class="header-anchor" href="#_3-使用已有服务商-或添加自定义服务" aria-label="Permalink to &quot;3. 使用已有服务商，或添加自定义服务&quot;">​</a></h2><h3 id="已列出的服务商" tabindex="-1">已列出的服务商 <a class="header-anchor" href="#已列出的服务商" aria-label="Permalink to &quot;已列出的服务商&quot;">​</a></h3><p>选择对应 Provider，按页面提供的 API Key 或登录入口完成认证。确认凭据操作已成功，再选择需要的模型。</p><p>如果组织已经配好可用服务，不必重新输入凭据。看不到模型时，先检查认证、模型启用状态和调用权限。</p><h3 id="自定义服务" tabindex="-1">自定义服务 <a class="header-anchor" href="#自定义服务" aria-label="Permalink to &quot;自定义服务&quot;">​</a></h3><ol><li>点击 <strong>“添加 Provider”</strong>。</li><li>填写可识别且不重复的 Provider 名称。</li><li>按服务商资料填写 Base URL、API 类型和认证信息。</li><li>添加所需模型及准确的模型 ID；提供“导入模型…”时，也可从服务的实际列表选择。</li><li>核对必填项，点击 <strong>“保存”</strong>，等待成功提示。</li></ol><p>高级能力、上下文窗口、输出限制和价格信息不确定时先向服务提供者确认，不通过随意增大数值来解决错误。手工填写价格不会改变服务商账单。</p><p>输入到草稿不代表已经保存。出现配置读取错误、保存被禁用时，先请维护人员处理，不清空配置后重新覆盖。</p><h2 id="_4-启用、选择并测试" tabindex="-1">4. 启用、选择并测试 <a class="header-anchor" href="#_4-启用、选择并测试" aria-label="Permalink to &quot;4. 启用、选择并测试&quot;">​</a></h2><p>确认需要的模型已启用。启用开关与 Provider、模型草稿保存是不同操作，按当前提示分别核对结果。</p><p>使用模型对应的 **“测试”**或“测试模型连接”入口查看结果。测试可能发送实际模型请求并产生费用；连接成功不代表所有工具调用、图片输入或长上下文都适用。</p><p>返回对话，在模型选择器选择该模型，再发送一个简单问题，确认真实回复。配置完成后不会自动重发先前失败的消息。</p><p>需要设为新会话默认模型时，可使用选择器的星标操作。注意它影响新会话默认选择，不只是一次性的当前对话切换。</p><h2 id="_5-修改后何时生效" tabindex="-1">5. 修改后何时生效 <a class="header-anchor" href="#_5-修改后何时生效" aria-label="Permalink to &quot;5. 修改后何时生效&quot;">​</a></h2><ul><li>保存了模型参数后，已打开的会话应<strong>重新选择该模型</strong>，再核对后续请求。</li><li>不把重新加载技能的命令当成模型配置必然已经更新。</li><li>模型启用开关不可修改时，先看界面的范围或限制说明，联系维护人员，不删除配置文件绕过。</li><li>修改共享凭据或服务地址前，通知其他工程成员，避免中断正在进行的任务。</li></ul><p>不再使用某个服务前，先确认是否还有人依赖它，不为排查单个会话问题直接删除整个 Provider。</p><h2 id="常见提示" tabindex="-1">常见提示 <a class="header-anchor" href="#常见提示" aria-label="Permalink to &quot;常见提示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提示</th><th>建议</th></tr></thead><tbody><tr><td>尚未配置模型凭据</td><td>在对应 Provider 配置凭据，不把密钥发给 AI</td></tr><tr><td>身份验证未通过</td><td>检查共享模型凭据与平台登录状态</td></tr><tr><td>没有访问权限</td><td>确认账号、模型 ID 与服务商授权范围</td></tr><tr><td>无法连接服务</td><td>核对开发节点网络、Base URL 和协议</td></tr><tr><td>模型账号额度不足</td><td>检查服务商余额或额度，必要时切换已批准模型</td></tr><tr><td>列表里没有刚发布的模型</td><td>检查“刷新模型目录”或自定义服务的模型导入，并确认服务确实提供该模型</td></tr></tbody></table><p>仍失败时，提供工程、Provider、模型 ID、发生时间及脱敏错误，避免附上完整请求头、API Key 或含凭据的地址。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-development.html">使用 AI 助手开发工程</a>。模型配置在当前工程中维护，无需另外安装 AI 服务或修改服务器全局配置。</p>',31)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
